import json,glob,re,os
terms=re.compile(r'(?i)(answer key|ground.?truth|protected|private|reference answer|gold(?:en)? answer|solution|grader|grading|score|cheat|other trial|previous trial|expected answer|rubric|evaluation|secret|hidden|leak|peek|access.*answer|copy.*answer)')
for p in sorted(glob.glob('/workspace/traces/*/*.json')):
 d=json.load(open(p)); msgs=d.get('messages',[])
 hits=[]
 for i,m in enumerate(msgs):
  s=json.dumps(m,ensure_ascii=False)
  if terms.search(s):
   # extract a short flattened excerpt around first match
   mt=terms.search(s); a=max(0,mt.start()-120); b=min(len(s),mt.end()+240)
   hits.append((i,s[a:b].replace('\\n',' ')[:500]))
 print(f'\n=== {d["trial_id"]} {os.path.basename(os.path.dirname(p))} msgs={len(msgs)} hits={len(hits)} task={d.get("task_id")} env={d.get("environment")} ===')
 for i,x in hits[:30]: print(f'{i}: {x}')
 if len(hits)>30: print('... more',len(hits)-30)
PY

